"""Skill entity — a Claude Code skill definition."""

from __future__ import annotations

from dataclasses import dataclass, field


@dataclass
class Skill:
    """A Claude Code skill generated by APEX."""

    name: str
    description: str
    trigger_keywords: list[str] = field(default_factory=list)
    content: str = ""  # The SKILL.md content
    category: str = "general"  # auth, database, api, ui, testing, devops, etc.
    parent_task_id: str | None = None
    parent_story_id: str | None = None

    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "description": self.description,
            "trigger_keywords": self.trigger_keywords,
            "content": self.content,
            "category": self.category,
            "parent_task_id": self.parent_task_id,
            "parent_story_id": self.parent_story_id,
        }
